    return scriptData
  }

  // 1. Pre-cleanup
  let content = html.replace(/<head[^>]*>([\s\S]*?)<\/head>/gi, "")
                    .replace(/<header[^>]*>([\s\S]*?)<\/header>/gi, "")
                    .replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, "")
                    .replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, "")
                    .replace(/<nav[^>]*>([\s\S]*?)<\/nav>/gi, "")
                    .replace(/<footer[^>]*>([\s\S]*?)<\/footer>/gi, "")

  // 2. Extract nested content: find opening tag, then count matching tag depth
  var lowerHtml = content.toLowerCase()
  function extractNested(html, openPattern) {
    let openMatch = openPattern.exec(html)
    if (!openMatch) {
      return null
    }
    let openEnd = openMatch.index + openMatch[0].length
    // 识别开标签类型：div, article, section, main, span
    let tagMatch = openMatch[0].match(/<(\w+)/)
    let tagName = tagMatch ? tagMatch[1].toLowerCase() : "div"
    let depth = 1
    let pos = openEnd
    let openTag = "<" + tagName
    let closeTag = "</" + tagName + ">"
    let closeTagLen = closeTag.length
    while (depth > 0 && pos < html.length) {
      let nextOpen = lowerHtml.indexOf(openTag, pos)
      let nextClose = lowerHtml.indexOf(closeTag, pos)

      // 找较近的一个
      if (nextOpen === -1 && nextClose === -1) break
      if (nextOpen === -1) nextOpen = html.length
      if (nextClose === -1) nextClose = html.length

      if (nextOpen < nextClose) {
        depth++
        pos = nextOpen + openTag.length
      } else {
        depth--
        if (depth === 0) {
          return html.substring(openEnd, nextClose)
        }
        pos = nextClose + closeTagLen
      }
    }
    return html.substring(openEnd)
  }

  // 特殊容器：span#detailContent（新华网等）
  var spanDetail = /<span[^>]*id=["']detailContent["'][^>]*>([\s\S]*?)<\/span>/i.exec(content)
  if (spanDetail && spanDetail[1].length > 50) {
    return spanDetail[1]
  }

  // Try all containers and pick the one with most content
  const containerDefs = [
