    { name: "div#article", pattern: /<div[^>]*id=["']article["'][^>]*>/i },
    { name: "div#detail", pattern: /<div[^>]*id=["']detail["'][^>]*>/i },
    { name: "div#content", pattern: /<div[^>]*id=["']content["'][^>]*>/i },
