154	          pos = fClose === -1 ? len : fClose + fTag.length + 3
155	          skipEx = true
156	          break
157	        }
158	      }
159	      if (skipEx) continue
160	
161	      if (lower.indexOf("<p", lt2) === lt2 &&
162	          (lt2 + 2 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 2)) !== -1)) {
163	        var pEnd = lower.indexOf("</p>", lt2 + 2)
164	        if (pEnd === -1) break
165	        var t = html.substring(lt2, pEnd + 4)
166	        if (t.length > 10) {
167	          res.push({ text: t, len: t.length, score: 0, isAd: false })
168	          if (res.length >= MAX_P) break
169	        }
170	        pos = pEnd + 4
171	        continue
172	      }
173	
174	      if (lower.indexOf("<script", lt2) === lt2 &&
175	          (lt2 + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 7)) !== -1)) {
176	        var scrEnd = lower.indexOf("</script>", lt2 + 7)
177	        pos = scrEnd === -1 ? len : scrEnd + 9
178	        continue
179	      }
180	      if (lower.indexOf("<style", lt2) === lt2 &&
181	          (lt2 + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 6)) !== -1)) {
182	        var styEnd = lower.indexOf("</style>", lt2 + 6)
183	        pos = styEnd === -1 ? len : styEnd + 8
184	        continue
185	      }
186	
187	      pos = lt2 + 1
