194	// ===== Step 2: 结构过滤（长度桶 + 区间相似性） =====
195	
196	function getBucket(len) {
197	  if (len < 20) return 0
198	  if (len < 50) return 1
199	  if (len < 100) return 2
200	  if (len < 200) return 3
201	  if (len < 400) return 4
202	  return 5
203	}
204	
205	function isSimilar(a, b) {
206	  var ba = getBucket(a)
207	  var bb = getBucket(b)
208	  var diff = Math.abs(a - b)
209	  // 同桶
210	  if (ba === bb) {
211	    if (a < 32 || b < 32) return diff <= 4
212	    return diff <= (Math.min(a, b) >> 3)
213	  }
214	  // 邻桶
215	  if (Math.abs(ba - bb) === 1) {
216	    return diff <= Math.floor(Math.min(a, b) * 20 / 100)
217	  }
218	  return false
219	}
220	
221	function structFilter(ps) {
222	  for (var i = 2; i < ps.length; i++) {
223	    if (isSimilar(ps[i].len, ps[i - 1].len) && isSimilar(ps[i].len, ps[i - 2].len)) {
224	      ps[i].isAd = true
225	    }
226	  }
227	}
