229	// ===== Step 3: 基础评分（整数版） =====
230	
231	function baseScore(p) {
232	  var s = 0
233	  var text = p.text
234	  var len = text.length
235	
236	  // 中文密度
237	  var han = 0
238	  for (var i = 0; i < len; i++) {
239	    var c = text.charCodeAt(i)
240	    if (c >= 0x4e00 && c <= 0x9fa5) han++
241	  }
242	  var ratio = (han * INT_SCALE) / (len + 1)
243	  if (ratio > 700) s += 300
244	  else s -= 100
245	
246	  // 末尾标点（取 HTML 内最后一个非空白字符）
247	  var lastChar = ""
248	  for (var j = len - 1; j >= 0; j--) {
249	    var ch = text.charAt(j)
250	    if (ch !== " " && ch !== "\n" && ch !== "\r" && ch !== "\t" && ch !== ">") {
251	      lastChar = ch
252	      break
253	    }
254	  }
255	  if (lastChar === "。" || lastChar === "！" || lastChar === "？") {
256	    s += 300
257	  } else {
258	    s -= 50
259	  }
260	
261	  // 副标题弱增强
262	  if (len < 18) {
263	    s += 80
264	  }
265	
266	  return s
267	}
