269	// ===== Step 4: 单向邻域增强（i-1） =====
270	
271	function smooth(ps) {
272	  var out = []
273	  for (var i = 0; i < ps.length; i++) {
274	    var s = ps[i].score
275	    if (i > 0 && !ps[i].isAd && !ps[i - 1].isAd) {
276	      s += Math.floor(ps[i - 1].score * 3 / 10)
277	    }
278	    out.push(s)
279	  }
280	  return out
281	}
