283	// ===== Step 5: Kadane-lite 最大子段和 =====
284	
285	function kadane(arr) {
286	  var max = -1000000000
287	  var sum = 0
288	  var start = 0
289	  var bestL = 0
290	  var bestR = 0
291	
292	  for (var i = 0; i < arr.length; i++) {
293	    if (sum <= 0) {
294	      sum = arr[i]
295	      start = i
296	    } else {
297	      sum += arr[i]
298	    }
299	    if (sum > max) {
300	      max = sum
301	      bestL = start
302	      bestR = i
303	    }
304	  }
305	
306	  return { bestL: bestL, bestR: bestR }
307	}
