309	// ===== SPA 检测 =====
310	
311	function isSPA(html) {
312	  var hasFramework = html.indexOf("__INITIAL_STATE__") !== -1 ||
313	                     html.indexOf("__DATA__") !== -1 ||
314	                     html.indexOf("window.__") !== -1
315	  var hasEmptyApp = (html.indexOf('id="app"') !== -1 || html.indexOf("id='app'") !== -1) &&
316	                    html.indexOf("<div") !== -1
317	  // SPA 壳子特征：有框架标记但正文极短
318	  var bodyLen = html.length
319	  var hasLittleContent = bodyLen < 5000
320	  return hasFramework && hasEmptyApp && hasLittleContent
321	}
