323	// ===== 主函数 =====
324	
325	function teckoR(html) {
326	  if (!html || html.length < 50) return ""
327	
328	  // Step 1: 提取段落
329	  var ps = extractP(html)
330	  if (ps.length === 0) return ""
331	
332	  // Step 2: 结构过滤
333	  structFilter(ps)
334	
335	  // Step 3: 基础评分
336	  for (var i = 0; i < ps.length; i++) {
337	    ps[i].score = baseScore(ps[i])
338	    if (ps[i].isAd) {
339	      ps[i].score = Math.min(ps[i].score, 10)
340	    }
341	  }
342	
343	  // Ring Buffer: 超出 MAX_P 时淘汰低分段
344	  if (ps.length > MAX_P) {
345	    ps.sort(function (a, b) { return b.score - a.score })
346	    ps = ps.slice(0, MAX_P)
347	  }
348	
349	  // Step 4: 单向邻域增强
350	  var sm = smooth(ps)
351	
352	  // Step 5: Kadane-lite
353	  var region = kadane(sm)
354	
355	  // 拼接输出
356	  var out = ""
357	  for (var j = region.bestL; j <= region.bestR; j++) {
358	    out += ps[j].text
359	  }
360	
361	  return out
362	}
